import androidx.lifecycle.LiveData
interface NotiRepository { fun getAllMessages(): LiveData<List<MessageModel>> suspend fun insertMessage(message: MessageModel) suspend fun markMessageAsDeleted(id: Int) suspend fun onWhatsAppNotificationReceived(message: MessageModel) suspend fun markMessageAsDeletedByDetails(sender: String, message: String, timestamp: Long) }

package com.notireader.app.domain

import android.service.notification.NotificationListenerService
import android.service.notification.StatusBarNotification
import dagger.hilt.android.AndroidEntryPoint
import javax.inject.Inject
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

@AndroidEntryPoint
class WhatsAppNotificationListener : NotificationListenerService() {
    @Inject
    lateinit var notiRepository: NotiRepository

    var title: String? = ""
    var message: CharSequence? = ""
    var timeStamp: Long = 0
    var isDeleted: Boolean = false

    override fun onNotificationPosted(sbn: StatusBarNotification?) {
        super.onNotificationPosted(sbn)
        if (sbn?.packageName == "com.whatsapp") {
            val title = sbn.notification.extras.getString("android.title") ?: ""
            val message = sbn.notification.extras.getCharSequence("android.text")?.toString() ?: ""
            val timeStamp = sbn.postTime
            val messageModel = MessageModel(
                sender = title,
                message = message,
                timestamp = timeStamp,
                isDeleted = false
            )
            CoroutineScope(Dispatchers.IO).launch {
                notiRepository.onWhatsAppNotificationReceived(messageModel)
            }
        }
    }

    override fun onNotificationRemoved(sbn: StatusBarNotification?, rankingMap: RankingMap?, reason: Int) {
        super.onNotificationRemoved(sbn, rankingMap, reason)
        if (sbn?.packageName == "com.whatsapp") {
            if(reason == REASON_APP_CANCEL) {
                isDeleted = true
            }
        }
    }
}

